  "ui.felleskostnader-power-internet-contents": ["Felleskostnader, power, internet, contents insurance … – shared every month. Add them once: your part goes into your budget, and when one of you pays the bill the other’s part is a claim to settle within 40 days.", "Felleskostnader, strøm, internett, innboforsikring … – delt hver måned. Legg dem inn én gang: din del går inn i budsjettet, og når en av dere betaler regningen, er den andres del et krav som gjøres opp innen 40 dager."],
  "ui.fh-add-your-accounts-4-steps": ["Add your accounts, your salary and what goes out each month – 4 short steps. Then this shows what you can really use until payday, what’s coming, and where it all goes.", "Legg inn kontoene dine, lønna og det som går ut hver måned – 4 korte steg. Da viser denne hva du faktisk kan bruke fram til lønning, hva som kommer, og hvor alt går."],
